export const bookmarksRouter = Router();

/**
 * Handles GET /api/v1/bookmarks - Lists bookmarks with pagination support.
 *
 * @param req - Express request with optional `page` and `limit` query parameters.
 * @param res - Express response sending paginated bookmark results.
 * @returns Void.
 *
 * @example
 * ```ts
 * // GET /api/v1/bookmarks?page=1&limit=20
 * bookmarksRouter.get('/', listBookmarksHandler);
 * ```
 */
export function listBookmarksHandler(req: Request, res: Response): void {
  const query = req.query as Record<string, unknown>;
  const { page, limit } = parsePaginationParams(query);
  const paginatedResult = bookmarkService.getPaginated(page, limit);
  res.status(200).json(paginatedResult);
}

/**
 * Handles GET /api/v1/bookmarks/search - Searches bookmarks by title or tags.
 *
 * @param req - Express request with required non-empty `q` query parameter.
 * @param res - Express response sending matching bookmarks or 400 error.
 * @returns Void.
 *
 * @example
 * ```ts
 * // GET /api/v1/bookmarks/search?q=typescript
 * bookmarksRouter.get('/search', searchBookmarksHandler);
 * ```
 */
export function searchBookmarksHandler(req: Request, res: Response): void {
  const rawQ = getQueryString(req.query.q);
  if (rawQ === undefined || rawQ.trim() === '') {
    res.status(400).json({ error: 'Search query parameter "q" is required and cannot be empty' });
    return;
  }

  const results = bookmarkService.search(rawQ);
  res.status(200).json(results);
}

/**
 * Handles GET /api/v1/bookmarks/:id - Retrieves a single bookmark by its ID.
 *
 * @param req - Express request containing the bookmark ID parameter.
 * @param res - Express response sending the bookmark or 404 error.
 * @returns Void.
 *
 * @example
 * ```ts
 * // GET /api/v1/bookmarks/123e4567-e89b-12d3-a456-426614174000
 * bookmarksRouter.get('/:id', getBookmarkByIdHandler);
 * ```
 */
export function getBookmarkByIdHandler(req: Request, res: Response): void {
  const rawId = req.params.id;
  const id = typeof rawId === 'string' ? rawId : undefined;

  if (!id) {
    res.status(404).json({ error: 'Bookmark not found' });
    return;
  }

  const bookmark = bookmarkService.getById(id);

  if (!bookmark) {
    res.status(404).json({ error: 'Bookmark not found' });
    return;
  }

  res.status(200).json(bookmark);
}

/**
 * Handles POST /api/v1/bookmarks - Creates a new bookmark.
 *
 * @param req - Express request containing the bookmark creation payload in body.
 * @param res - Express response sending the created bookmark with 201 or error status.
 * @param next - Express next middleware function for error delegation.
 * @returns Void.
 *
 * @example
 * ```ts
 * // POST /api/v1/bookmarks
 * // Body: { "url": "https://example.com", "title": "Example", "tags": ["web"] }
 * bookmarksRouter.post('/', createBookmarkHandler);
 * ```
 */
export function createBookmarkHandler(req: Request, res: Response, next: NextFunction): void {
  const body: unknown = req.body;
  const result = createBookmarkSchema.safeParse(body);

  if (!result.success) {
    next(result.error);
    return;
  }

  try {
    const created = bookmarkService.create(result.data);
    res.status(201).json(created);
  } catch (err: unknown) {
    if (err instanceof DuplicateBookmarkError) {
      res.status(409).json({ error: err.message });
      return;
    }
    next(err);
  }
}

/**
 * Handles PATCH /api/v1/bookmarks/:id - Updates an existing bookmark's title and/or tags.
 *
 * @param req - Express request containing bookmark ID in params and updates in body.
 * @param res - Express response sending updated bookmark or error status.
 * @param next - Express next middleware function for validation error delegation.
 * @returns Void.
 *
 * @example
 * ```ts
 * // PATCH /api/v1/bookmarks/123e4567-e89b-12d3-a456-426614174000
 * // Body: { "title": "New Title" }
 * bookmarksRouter.patch('/:id', updateBookmarkHandler);
 * ```
 */
export function updateBookmarkHandler(req: Request, res: Response, next: NextFunction): void {
  const rawId = req.params.id;
  const id = typeof rawId === 'string' ? rawId : undefined;

  if (!id) {
    res.status(404).json({ error: 'Bookmark not found' });
    return;
  }

  const body: unknown = req.body;
  if (typeof body === 'object' && body !== null && 'url' in body && (body as { url: unknown }).url !== undefined) {
    res.status(400).json({ error: 'URL is immutable and cannot be updated' });
    return;
  }

  const result = updateBookmarkSchema.safeParse(body);
  if (!result.success) {
    next(result.error);
    return;
  }

  const updated = bookmarkService.update(id, result.data);
  if (!updated) {
    res.status(404).json({ error: 'Bookmark not found' });
    return;
  }

  res.status(200).json(updated);
}

/**
 * Handles DELETE /api/v1/bookmarks/:id - Deletes a bookmark by ID.
 *
 * @param req - Express request containing bookmark ID parameter.
 * @param res - Express response sending 204 No Content or 404 Not Found.
