export function searchBookmarksHandler(req: Request, res: Response): void {
  const rawQ = getQueryString(req.query.q);
  if (rawQ === undefined || rawQ.trim() === '') {
    res.status(400).json({ error: 'Search query parameter "q" is required and cannot be empty' });
    return;
  }

  const results = bookmarkService.search(rawQ);
  res.status(200).json(results);
}

