function isCreateBookmarkDTO(value: unknown): value is CreateBookmarkDTO {
  if (typeof value !== 'object' || value === null) {
    return false;
  }
  const record = value as Record<string, unknown>;
  if (typeof record.url !== 'string') {
    return false;
  }
  if (record.title !== undefined && typeof record.title !== 'string') {
    return false;
  }
  if (
    record.tags !== undefined &&
    (!Array.isArray(record.tags) || !record.tags.every((tag: unknown): boolean => typeof tag === 'string'))
  ) {
    return false;
  }
  return true;
}

export const bookmarksRouter = Router();

export function createBookmarkHandler(req: Request, res: Response): void {
  const body: unknown = req.body;

  if (!isCreateBookmarkDTO(body)) {
    res.status(400).json({ error: 'Invalid bookmark payload' });
    return;
  }

  const bookmark: Bookmark = {
    id: crypto.randomUUID(),
    url: body.url,
    ...(body.title !== undefined ? { title: body.title } : {}),
    ...(body.tags !== undefined ? { tags: body.tags } : {}),
    createdAt: new Date().toISOString(),
  };

  res.status(201).json(bookmark);
}

