/**
 * Extracts a single string value from an unknown query parameter value.
 *
 * @param value - The raw query parameter value.
 * @returns The string representation if valid, otherwise undefined.
 *
 * @example
 * ```ts
 * const param = getQueryString(req.query.q);
 * ```
 */
function getQueryString(value: unknown): string | undefined {
  if (typeof value === 'string') {
    return value;
  }
  if (Array.isArray(value) && typeof value[0] === 'string') {
    return value[0];
  }
  return undefined;
}

/**
 * Parses and bounds pagination query parameters (page and limit).
 *
 * @param query - Request query object.
 * @returns An object with validated `page` (minimum 1) and `limit` (clamped between 1 and 100).
 *
 * @example
 * ```ts
 * const { page, limit } = parsePaginationParams(req.query);
 * ```
 */
export function parsePaginationParams(query: Record<string, unknown>): { page: number; limit: number } {
  let page = 1;
  let limit = 20;

  const rawPage = getQueryString(query.page);
  if (rawPage !== undefined) {
    const parsed = parseInt(rawPage, 10);
    if (!Number.isNaN(parsed)) {
      page = Math.max(1, parsed);
    }
  }

  const rawLimit = getQueryString(query.limit);
  if (rawLimit !== undefined) {
    const parsed = parseInt(rawLimit, 10);
    if (!Number.isNaN(parsed)) {
      limit = Math.min(100, Math.max(1, parsed));
    }
  }

  return { page, limit };
}

export const bookmarksRouter = Router();

/**
 * Handles GET /api/v1/bookmarks - Lists bookmarks with pagination support.
 *
 * @param req - Express request with optional `page` and `limit` query parameters.
 * @param res - Express response sending paginated bookmark results.
 * @returns Void.
 *
 * @example
 * ```ts
 * // GET /api/v1/bookmarks?page=1&limit=20
 * bookmarksRouter.get('/', listBookmarksHandler);
 * ```
 */
export function listBookmarksHandler(req: Request, res: Response): void {
  const query = req.query as Record<string, unknown>;
  const { page, limit } = parsePaginationParams(query);
  const paginatedResult = bookmarkService.getPaginated(page, limit);
  res.status(200).json(paginatedResult);
}

