import { Router, type Request, type Response, type NextFunction } from 'express';
import { z } from 'zod';
import {
  bookmarkService,
  DuplicateBookmarkError,
  type Bookmark,
} from '../services/bookmark-service.js';

export const createBookmarkSchema = z.object({
  url: z.string().url().max(2048),
  title: z.string().max(200).optional(),
  tags: z.array(z.string().max(50)).max(10).optional(),
});

export type CreateBookmarkDTO = z.infer<typeof createBookmarkSchema>;
export type CreateBookmarkInput = CreateBookmarkDTO;
export type { Bookmark };

export const bookmarksRouter = Router();

export function createBookmarkHandler(
  req: Request,
  res: Response,
  next: NextFunction
): void {
  const body: unknown = req.body;
  const result = createBookmarkSchema.safeParse(body);

  if (!result.success) {
    res.status(400).json({ error: 'Validation failed', details: result.error.issues });
    return;
  }

  try {
    const created = bookmarkService.create(result.data);
    res.status(201).json(created);
  } catch (err: unknown) {
    if (err instanceof DuplicateBookmarkError) {
      res.status(409).json({ error: err.message });
      return;
    }
    next(err);
  }
}

bookmarksRouter.post('/', createBookmarkHandler);

