import { describe, it, expect, beforeEach } from 'vitest';
import request from 'supertest';
import { app } from '../src/app.js';
import { bookmarkService, type Bookmark } from '../src/services/bookmark-service.js';

describe('Bookmarks API Integration Tests', () => {
  beforeEach(() => {
    bookmarkService.clear();
  });

  describe('POST /api/v1/bookmarks', () => {
    it('should create a new bookmark and return 201 with the created object', async () => {
      const payload = {
        url: 'https://example.com/integration-test',
        title: 'Integration Test Bookmark',
        tags: ['integration', 'test'],
      };

      const response = await request(app)
        .post('/api/v1/bookmarks')
        .send(payload)
        .set('Accept', 'application/json');

      expect(response.status).toBe(201);
      const body = response.body as Bookmark;
      expect(body.id).toBeDefined();
      expect(typeof body.id).toBe('string');
      expect(body.url).toBe(payload.url);
      expect(body.title).toBe(payload.title);
      expect(body.tags).toEqual(payload.tags);
      expect(body.createdAt).toBeDefined();
      expect(Number.isNaN(Date.parse(body.createdAt))).toBe(false);
    });
  });

  describe('GET /api/v1/bookmarks (list)', () => {
    it('should return a list of all bookmarks sorted by createdAt descending', async () => {
      const first = bookmarkService.create({
        url: 'https://example.com/first',
        title: 'First',
      });
      await new Promise<void>((resolve) => setTimeout(resolve, 5));
      const second = bookmarkService.create({
        url: 'https://example.com/second',
        title: 'Second',
      });

      const response = await request(app)
        .get('/api/v1/bookmarks')
        .set('Accept', 'application/json');

      expect(response.status).toBe(200);
      const body = response.body as Bookmark[];
      expect(Array.isArray(body)).toBe(true);
      expect(body.length).toBe(2);
      expect(body[0].id).toBe(second.id);
      expect(body[1].id).toBe(first.id);
    });
  });

  describe('GET /api/v1/bookmarks/:id (single)', () => {
    it('should return a single bookmark by id with 200 OK', async () => {
      const created = bookmarkService.create({
        url: 'https://example.com/single',
        title: 'Single Item',
        tags: ['single'],
      });

      const response = await request(app)
        .get(`/api/v1/bookmarks/${created.id}`)
        .set('Accept', 'application/json');

      expect(response.status).toBe(200);
      const body = response.body as Bookmark;
      expect(body.id).toBe(created.id);
      expect(body.url).toBe(created.url);
      expect(body.title).toBe(created.title);
      expect(body.tags).toEqual(created.tags);
    });
  });

  describe('DELETE /api/v1/bookmarks/:id', () => {
    it('should delete an existing bookmark and return 204 No Content', async () => {
      const created = bookmarkService.create({
        url: 'https://example.com/to-delete',
        title: 'To Delete',
      });

      const deleteResponse = await request(app)
        .delete(`/api/v1/bookmarks/${created.id}`);

      expect(deleteResponse.status).toBe(204);

      const getResponse = await request(app)
        .get(`/api/v1/bookmarks/${created.id}`);

      expect(getResponse.status).toBe(404);
    });
  });
});

