import { describe, it, expect, vi } from 'vitest';
import request from 'supertest';
import { EventEmitter } from 'node:events';
import type { Request, Response, NextFunction } from 'express';
import { requestLogger, type RequestLog } from './request-logger.js';
import { app } from '../app.js';

describe('requestLogger middleware', () => {
  it('calls next() and logs JSON on response finish', () => {
    const consoleSpy = vi.spyOn(console, 'log').mockImplementation(() => {});

    const req = {
      method: 'GET',
      path: '/api/v1/bookmarks',
      originalUrl: '/api/v1/bookmarks',
    } as unknown as Request;

    const resEmitter = new EventEmitter();
    const res = Object.assign(resEmitter, {
      statusCode: 200,
    }) as unknown as Response;

    const next = vi.fn() as unknown as NextFunction;

    requestLogger(req, res, next);

    expect(next).toHaveBeenCalledOnce();
    expect(consoleSpy).not.toHaveBeenCalled();

    resEmitter.emit('finish');

    expect(consoleSpy).toHaveBeenCalledOnce();
    const loggedRaw = consoleSpy.mock.calls[0]?.[0];
    expect(typeof loggedRaw).toBe('string');

    const parsed: unknown = JSON.parse(loggedRaw as string);
    const log = parsed as RequestLog;

    expect(log.method).toBe('GET');
    expect(log.path).toBe('/api/v1/bookmarks');
    expect(log.status).toBe(200);
    expect(typeof log.duration_ms).toBe('number');
    expect(log.duration_ms).toBeGreaterThanOrEqual(0);

    consoleSpy.mockRestore();
  });

  it('logs during actual HTTP requests through Express app', async () => {
    const consoleSpy = vi.spyOn(console, 'log').mockImplementation(() => {});

    const response = await request(app).get('/health');
    expect(response.status).toBe(200);

    expect(consoleSpy).toHaveBeenCalled();
    const lastCall = consoleSpy.mock.calls[consoleSpy.mock.calls.length - 1]?.[0];
    expect(typeof lastCall).toBe('string');

    const log = JSON.parse(lastCall as string) as RequestLog;
    expect(log.method).toBe('GET');
    expect(log.path).toBe('/health');
    expect(log.status).toBe(200);
    expect(typeof log.duration_ms).toBe('number');
    expect(log.duration_ms).toBeGreaterThanOrEqual(0);

    consoleSpy.mockRestore();
  });
});

