import { randomUUID } from 'node:crypto';

export class DuplicateBookmarkError extends Error {
  constructor(message = 'Bookmark with this URL already exists') {
    super(message);
    this.name = 'DuplicateBookmarkError';
  }
}

export interface Bookmark {
  id: string;
  url: string;
  title?: string;
  tags?: string[];
  createdAt: string;
}

export interface CreateBookmarkDTO {
  url: string;
  title?: string;
  tags?: string[];
}

export interface UpdateBookmarkDTO {
  title?: string;
  tags?: string[];
}

export interface PaginationMeta {
  page: number;
  limit: number;
  total: number;
  totalPages: number;
}

export interface PaginatedResult<T> {
  data: T[];
  pagination: PaginationMeta;
}

export class BookmarkService {
  private bookmarks: Map<string, Bookmark> = new Map();

  /**
   * Creates and stores a new bookmark.
   *
   * @param data - The bookmark data containing a required URL and optional title and tags.
   * @returns The newly created bookmark with generated ID and creation timestamp.
   * @throws {DuplicateBookmarkError} If a bookmark with the same URL already exists.
   *
   * @example
   * ```ts
   * const bookmark = bookmarkService.create({
   *   url: 'https://example.com',
   *   title: 'Example Domain',
   *   tags: ['example', 'web'],
   * });
   * console.log(bookmark.id);
   * ```
   */
  create(data: CreateBookmarkDTO): Bookmark {
    for (const bookmark of this.bookmarks.values()) {
      if (bookmark.url === data.url) {
        throw new DuplicateBookmarkError(`Bookmark with URL "${data.url}" already exists`);
      }
    }

    const id = randomUUID();
    const bookmark: Bookmark = {
      id,
      url: data.url,
      title: data.title,
      tags: data.tags ? [...data.tags] : undefined,
      createdAt: new Date().toISOString(),
    };

    this.bookmarks.set(id, bookmark);
    return bookmark;
  }

  /**
   * Retrieves a bookmark by its unique identifier.
   *
   * @param id - The unique string ID of the bookmark.
   * @returns The matching bookmark if found, or undefined if not found.
   *
   * @example
   * ```ts
   * const bookmark = bookmarkService.getById('e26c11a2-4a7b-4be5-94cf-e48f76024d26');
   * if (bookmark) {
   *   console.log(bookmark.title);
   * }
   * ```
   */
  getById(id: string): Bookmark | undefined {
    return this.bookmarks.get(id);
  }

  /**
   * Retrieves all bookmarks sorted by creation date in descending order (newest first).
   *
   * @returns An array of all bookmarks sorted newest first.
   *
   * @example
   * ```ts
   * const allBookmarks = bookmarkService.getAll();
   * console.log(`Total bookmarks: ${allBookmarks.length}`);
   * ```
   */
  getAll(): Bookmark[] {
    return Array.from(this.bookmarks.values()).sort(
      (a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()
    );
  }

  /**
   * Retrieves a paginated subset of bookmarks sorted by creation date descending.
   *
   * @param page - 1-based page number.
   * @param limit - Maximum number of items per page.
   * @returns A paginated result containing the page's bookmarks and pagination metadata.
   *
   * @example
   * ```ts
   * const result = bookmarkService.getPaginated(1, 10);
   * console.log(result.data);
   * console.log(result.pagination.totalPages);
   * ```
   */
  getPaginated(page: number, limit: number): PaginatedResult<Bookmark> {
    const all = this.getAll();
    const total = all.length;
    const totalPages = Math.ceil(total / limit);
    const offset = (page - 1) * limit;
    const data = all.slice(offset, offset + limit);

    return {
      data,
      pagination: {
        page,
        limit,
        total,
        totalPages,
      },
    };
  }

  /**
   * Updates the title and/or tags of an existing bookmark. URL cannot be changed.
   *
   * @param id - The unique identifier of the bookmark to update.
   * @param data - The fields to update (optional title and/or tags).
   * @returns The updated bookmark if found, or undefined if the bookmark does not exist.
   *
   * @example
   * ```ts
   * const updated = bookmarkService.update('e26c11a2-4a7b-4be5-94cf-e48f76024d26', {
   *   title: 'Updated Title',
   *   tags: ['new-tag'],
   * });
   * ```
   */
  update(id: string, data: UpdateBookmarkDTO): Bookmark | undefined {
    const existing = this.bookmarks.get(id);
    if (!existing) {
      return undefined;
    }

    const updated: Bookmark = {
      ...existing,
      title: data.title !== undefined ? data.title : existing.title,
      tags: data.tags !== undefined ? [...data.tags] : existing.tags,
    };

    this.bookmarks.set(id, updated);
    return updated;
  }

  /**
   * Searches bookmarks by title (case-insensitive substring) and tags (exact match).
   *
   * @param query - The search query term.
   * @returns An array of matching bookmarks sorted newest first.
   *
   * @example
   * ```ts
   * const matches = bookmarkService.search('typescript');
   * matches.forEach((b) => console.log(b.title));
   * ```
   */
  search(query: string): Bookmark[] {
    const trimmed = query.trim();
    if (!trimmed) {
      return [];
    }
    const lower = trimmed.toLowerCase();
    return this.getAll().filter((bookmark) => {
      const titleMatch =
        bookmark.title !== undefined &&
        bookmark.title.toLowerCase().includes(lower);
      const tagMatch =
        bookmark.tags !== undefined &&
        bookmark.tags.some(
          (tag) => tag.toLowerCase() === lower || tag === trimmed
        );
      return titleMatch || tagMatch;
    });
  }

  /**
   * Deletes a bookmark by its unique identifier.
   *
   * @param id - The unique identifier of the bookmark to delete.
   * @returns True if the bookmark was found and deleted, false if not found.
   *
   * @example
   * ```ts
   * const deleted = bookmarkService.delete('e26c11a2-4a7b-4be5-94cf-e48f76024d26');
   * if (deleted) {
   *   console.log('Bookmark removed');
   * }
   * ```
   */
  delete(id: string): boolean {
    return this.bookmarks.delete(id);
  }

  /**
   * Removes all bookmarks from memory.
   *
   * @returns Void.
   *
   * @example
   * ```ts
   * bookmarkService.clear();
   * console.log(bookmarkService.getAll().length); // 0
   * ```
   */
  clear(): void {
    this.bookmarks.clear();
  }
}

export const bookmarkService = new BookmarkService();

import { Router, type Request, type Response, type NextFunction } from 'express';
import { z } from 'zod';
import {
  bookmarkService,
  DuplicateBookmarkError,
  type Bookmark,
  type PaginatedResult,
  type PaginationMeta,
  type UpdateBookmarkDTO,
} from '../services/bookmark-service.js';

export const createBookmarkSchema = z.object({
  url: z.string().url().max(2048),
  title: z.string().max(200).optional(),
  tags: z.array(z.string().max(50)).max(10).optional(),
});

export type CreateBookmarkDTO = z.infer<typeof createBookmarkSchema>;
export type CreateBookmarkInput = CreateBookmarkDTO;

export const updateBookmarkSchema = z.object({
  title: z.string().max(200).optional(),
  tags: z.array(z.string().max(50)).max(10).optional(),
});

export type { Bookmark, PaginatedResult, PaginationMeta, UpdateBookmarkDTO };
export type UpdateBookmarkInput = z.infer<typeof updateBookmarkSchema>;

/**
 * Extracts a single string value from an unknown query parameter value.
 *
 * @param value - The raw query parameter value.
 * @returns The string representation if valid, otherwise undefined.
 *
 * @example
 * ```ts
 * const param = getQueryString(req.query.q);
 * ```
 */
function getQueryString(value: unknown): string | undefined {
  if (typeof value === 'string') {
    return value;
  }
  if (Array.isArray(value) && typeof value[0] === 'string') {
    return value[0];
  }
  return undefined;
}

/**
 * Parses and bounds pagination query parameters (page and limit).
 *
 * @param query - Request query object.
 * @returns An object with validated `page` (minimum 1) and `limit` (clamped between 1 and 100).
 *
 * @example
 * ```ts
 * const { page, limit } = parsePaginationParams(req.query);
 * ```
 */
export function parsePaginationParams(query: Record<string, unknown>): { page: number; limit: number } {
  let page = 1;
  let limit = 20;

  const rawPage = getQueryString(query.page);
  if (rawPage !== undefined) {
    const parsed = parseInt(rawPage, 10);
    if (!Number.isNaN(parsed)) {
      page = Math.max(1, parsed);
    }
  }

  const rawLimit = getQueryString(query.limit);
  if (rawLimit !== undefined) {
    const parsed = parseInt(rawLimit, 10);
    if (!Number.isNaN(parsed)) {
      limit = Math.min(100, Math.max(1, parsed));
    }
  }

  return { page, limit };
}

export const bookmarksRouter = Router();

/**
 * Handles GET /api/v1/bookmarks - Lists bookmarks with pagination support.
 *
 * @param req - Express request with optional `page` and `limit` query parameters.
 * @param res - Express response sending paginated bookmark results.
 * @returns Void.
 *
 * @example
 * ```ts
 * // GET /api/v1/bookmarks?page=1&limit=20
 * bookmarksRouter.get('/', listBookmarksHandler);
 * ```
 */
export function listBookmarksHandler(req: Request, res: Response): void {
  const query = req.query as Record<string, unknown>;
  const { page, limit } = parsePaginationParams(query);
  const paginatedResult = bookmarkService.getPaginated(page, limit);
  res.status(200).json(paginatedResult);
}

/**
 * Handles GET /api/v1/bookmarks/search - Searches bookmarks by title or tags.
 *
 * @param req - Express request with required non-empty `q` query parameter.
 * @param res - Express response sending matching bookmarks or 400 error.
 * @returns Void.
 *
 * @example
 * ```ts
 * // GET /api/v1/bookmarks/search?q=typescript
 * bookmarksRouter.get('/search', searchBookmarksHandler);
 * ```
 */
export function searchBookmarksHandler(req: Request, res: Response): void {
  const rawQ = getQueryString(req.query.q);
  if (rawQ === undefined || rawQ.trim() === '') {
    res.status(400).json({ error: 'Search query parameter "q" is required and cannot be empty' });
    return;
  }

  const results = bookmarkService.search(rawQ);
  res.status(200).json(results);
}

/**
 * Handles GET /api/v1/bookmarks/:id - Retrieves a single bookmark by its ID.
 *
 * @param req - Express request containing the bookmark ID parameter.
 * @param res - Express response sending the bookmark or 404 error.
 * @returns Void.
 *
 * @example
 * ```ts
 * // GET /api/v1/bookmarks/123e4567-e89b-12d3-a456-426614174000
 * bookmarksRouter.get('/:id', getBookmarkByIdHandler);
 * ```
 */
export function getBookmarkByIdHandler(req: Request, res: Response): void {
  const rawId = req.params.id;
  const id = typeof rawId === 'string' ? rawId : undefined;

  if (!id) {
    res.status(404).json({ error: 'Bookmark not found' });
    return;
  }

  const bookmark = bookmarkService.getById(id);

  if (!bookmark) {
    res.status(404).json({ error: 'Bookmark not found' });
    return;
  }

  res.status(200).json(bookmark);
}

/**
 * Handles POST /api/v1/bookmarks - Creates a new bookmark.
 *
 * @param req - Express request containing the bookmark creation payload in body.
 * @param res - Express response sending the created bookmark with 201 or error status.
 * @param next - Express next middleware function for error delegation.
 * @returns Void.
 *
 * @example
 * ```ts
 * // POST /api/v1/bookmarks
 * // Body: { "url": "https://example.com", "title": "Example", "tags": ["web"] }
 * bookmarksRouter.post('/', createBookmarkHandler);
 * ```
 */
export function createBookmarkHandler(req: Request, res: Response, next: NextFunction): void {
  const body: unknown = req.body;
  const result = createBookmarkSchema.safeParse(body);

  if (!result.success) {
    next(result.error);
    return;
  }

  try {
    const created = bookmarkService.create(result.data);
    res.status(201).json(created);
  } catch (err: unknown) {
    if (err instanceof DuplicateBookmarkError) {
      res.status(409).json({ error: err.message });
      return;
    }
    next(err);
  }
}

/**
 * Handles PATCH /api/v1/bookmarks/:id - Updates an existing bookmark's title and/or tags.
 *
 * @param req - Express request containing bookmark ID in params and updates in body.
 * @param res - Express response sending updated bookmark or error status.
 * @param next - Express next middleware function for validation error delegation.
 * @returns Void.
 *
 * @example
 * ```ts
 * // PATCH /api/v1/bookmarks/123e4567-e89b-12d3-a456-426614174000
 * // Body: { "title": "New Title" }
 * bookmarksRouter.patch('/:id', updateBookmarkHandler);
 * ```
 */
export function updateBookmarkHandler(req: Request, res: Response, next: NextFunction): void {
  const rawId = req.params.id;
  const id = typeof rawId === 'string' ? rawId : undefined;

  if (!id) {
    res.status(404).json({ error: 'Bookmark not found' });
    return;
  }

  const body: unknown = req.body;
  if (typeof body === 'object' && body !== null && 'url' in body && (body as { url: unknown }).url !== undefined) {
    res.status(400).json({ error: 'URL is immutable and cannot be updated' });
    return;
  }

  const result = updateBookmarkSchema.safeParse(body);
  if (!result.success) {
    next(result.error);
    return;
  }

  const updated = bookmarkService.update(id, result.data);
  if (!updated) {
    res.status(404).json({ error: 'Bookmark not found' });
    return;
  }

  res.status(200).json(updated);
}

/**
 * Handles DELETE /api/v1/bookmarks/:id - Deletes a bookmark by ID.
 *
 * @param req - Express request containing bookmark ID parameter.
 * @param res - Express response sending 204 No Content or 404 Not Found.
 * @returns Void.
 *
 * @example
 * ```ts
 * // DELETE /api/v1/bookmarks/123e4567-e89b-12d3-a456-426614174000
 * bookmarksRouter.delete('/:id', deleteBookmarkHandler);
 * ```
 */
export function deleteBookmarkHandler(req: Request, res: Response): void {
  const rawId = req.params.id;
  const id = typeof rawId === 'string' ? rawId : undefined;

  if (!id) {
    res.status(404).json({ error: 'Bookmark not found' });
    return;
  }

  const deleted = bookmarkService.delete(id);
  if (!deleted) {
    res.status(404).json({ error: 'Bookmark not found' });
    return;
  }

  res.status(204).send();
}

